<script lang="ts" module>
  import type { GeneratedPassphrase, NewPassphrase } from "../api";

  /** What a form sends: the generated passphrase by token, else the typed text. */
  export function newPassphrase(generated: GeneratedPassphrase | null, typed: string): NewPassphrase {
    return generated ? { kind: "generated", token: generated.token } : { kind: "typed", value: typed };
  }
</script>

<script lang="ts">
  // A new sync passphrase (create, change, reset): typed with a confirmation
  // and the core's live estimate, or generated by the core (6 EFF words,
  // shown once, "I wrote it down" unless the dialog asks for it itself).
  // The core enforces the minimum (`sync_passphrase_weak`); the meter shows
  // what it will decide, in the warning tone while typing and the error tone
  // only once the core refused it. A copied passphrase leaves the clipboard
  // after 30 s (`secretclip.ts`).
  import { asError, type ErrorSummary, type PassphraseStrength } from "../api";
  import { backend } from "../backend";
  import { COPIED_NOTE, copySecret } from "../secretclip";
  import { strengthView } from "../syncview";
  import CodeText from "./CodeText.svelte";

  let {
    value = $bindable(""),
    confirm = $bindable(""),
    generated = $bindable(null),
    wroteDown = $bindable(false),
    ready = $bindable(false),
    label = "Passphrase",
    autofocus = false,
    savedOutside = false,
    refused = false,
    problem = null,
    onedit,
  }: {
    value?: string;
    confirm?: string;
    generated?: GeneratedPassphrase | null;
    wroteDown?: boolean;
    /** Acceptable, confirmed (or generated and written down). */
    ready?: boolean;
    label?: string;
    autofocus?: boolean;
    /** The dialog asks "I saved it" itself (the wizard): no "I wrote it down". */
    savedOutside?: boolean;
    /** The core refused this passphrase as too weak: the meter turns to error. */
    refused?: boolean;
    /** A refusal of this passphrase (`sync_passphrase_reused`…), shown under
     * its field; the dialog clears it through `onedit`. */
    problem?: { message: string; hint: string } | null;
    /** The passphrase was edited, generated, or typed again. */
    onedit?: () => void;
  } = $props();

  let strength: PassphraseStrength | null = $state(null);
  let generating = $state(false);
  let error: ErrorSummary | null = $state(null);
  let copied = $state(false);

  // The typed passphrase is estimated by the core (debounced); a stale
  // answer never replaces a newer one.
  let asked = 0;
  $effect(() => {
    const text = value;
    if (generated) return;
    if (!text) {
      strength = null;
      return;
    }
    const n = ++asked;
    const timer = setTimeout(() => {
      backend.syncAssessPassphrase(text).then(
        (s) => n === asked && (strength = s),
        () => n === asked && (strength = null),
      );
    }, 150);
    return () => clearTimeout(timer);
  });

  const shown = $derived(generated ? generated.strength : strength);
  const meter = $derived(shown ? strengthView(shown.estimatedBits, shown.acceptable) : null);
  const mismatch = $derived(!generated && confirm.length > 0 && confirm !== value);
  $effect(() => {
    ready = generated ? savedOutside || wroteDown : !!strength?.acceptable && value.length > 0 && confirm === value;
  });

  async function generate() {
    onedit?.();
    generating = true;
    error = null;
    try {
      generated = await backend.syncGeneratePassphrase();
      value = "";
      confirm = "";
      wroteDown = false;
      copied = false;
    } catch (e) {
      error = asError(e);
    } finally {
      generating = false;
    }
  }

  function typeOwn() {
    onedit?.();
    generated = null;
    wroteDown = false;
    copied = false;
    // Not used any more: Rust drops it now, not when the dialog closes.
    void backend.syncForgetGenerated().catch(() => {});
  }

  async function copy() {
    if (!generated) return;
    try {
      await copySecret(generated.text);
      copied = true;
    } catch (e) {
      error = asError(e);
    }
  }

  const tone = $derived(meter ? (meter.tone === "weak" && refused ? "refused" : meter.tone) : "empty");
</script>

{#if generated}
  <div class="generated" data-testid="sync-generated">
    <span class="caption">Generated passphrase · shown once</span>
    <code class="words">{generated.text}</code>
    <div class="row">
      <button class="secondary small" onclick={copy}>{copied ? "Copied" : "Copy"}</button>
      <button class="secondary small" onclick={generate} disabled={generating}>Generate another</button>
      <button class="secondary small" onclick={typeOwn}>Type my own</button>
    </div>
    <p class="note">Write it down or keep it in a password manager. Portico cannot show it again.</p>
    {#if copied}<p class="note" data-testid="sync-copied">{COPIED_NOTE}.</p>{/if}
    {#if !savedOutside}
      <label class="check"><input type="checkbox" bind:checked={wroteDown} data-autofocus={autofocus ? "" : undefined} /> I wrote it down</label>
    {/if}
  </div>
{:else}
  <label class="field">
    <span>{label}</span>
    <input
      type="password"
      bind:value
      autocomplete="new-password"
      spellcheck="false"
      data-autofocus={autofocus ? "" : undefined}
      aria-invalid={!!problem || (refused && !!strength && !strength.acceptable && value.length > 0)}
      aria-describedby={problem ? "sync-pass-problem sync-meter" : "sync-meter"}
      oninput={() => onedit?.()}
    />
  </label>
  {#if problem}
    <div class="inline-error" role="alert" id="sync-pass-problem" data-testid="sync-pass-problem">
      <span><CodeText text={problem.message} /></span>
      <span class="hint">{problem.hint}</span>
    </div>
  {/if}
  <label class="field">
    <span>Confirm</span>
    <input type="password" bind:value={confirm} autocomplete="new-password" spellcheck="false" aria-invalid={mismatch} oninput={() => onedit?.()} />
  </label>
  <div class="gen-row">
    <button class="secondary small" onclick={generate} disabled={generating}>
      {#if generating}<span class="spinner"></span>{/if}Generate a passphrase
    </button>
    <span class="note">6 random words, easy to type, hard to guess.</span>
  </div>
{/if}

<!-- Like a field: its word in the label column, the bar as wide as the fields. -->
<div class="meter" id="sync-meter" aria-live="polite">
  <span class="word" data-tone={tone}>
    {#if meter && shown}Strength · {meter.word} · <span class="mono">~{shown.estimatedBits} bits</span>{:else}Strength{/if}
  </span>
  <div class="track"><div class="fill" data-tone={tone} style:transform={`scaleX(${meter?.fill ?? 0})`}></div></div>
</div>
{#if meter && shown && !shown.acceptable}
  <span class="soft-warning">Not enough yet: at least about 60 bits, or 5 words of the generated kind. Add words, or generate one.</span>
{:else if mismatch}
  <span class="inline-error" role="alert">The passphrases differ.</span>
{/if}
{#if error}
  <div class="inline-error" role="alert"><span><CodeText text={error.message} /></span>{#if error.hint}<span class="hint"><CodeText text={error.hint} capitalize={false} /></span>{/if}</div>
{/if}

<style>
  .generated {
    display: grid;
    gap: var(--space-2);
    padding: var(--space-3) var(--space-4);
    border: 1px solid var(--border-strong);
    border-radius: var(--radius-md);
    background: var(--bg-elevated);
  }
  .caption { color: var(--text-muted); font-size: var(--text-xs); letter-spacing: var(--tracking-caps); text-transform: uppercase; }
  .words {
    color: var(--text-primary);
    font-family: var(--font-mono);
    font-size: var(--text-md);
    line-height: 1.6;
    word-spacing: 0.3em;
    user-select: all;
  }
  .row, .gen-row { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); }
  .meter { display: grid; gap: var(--space-1); }
  .track { height: 4px; overflow: hidden; border-radius: var(--radius-pill); background: var(--bg-elevated); }
  .fill {
    width: 100%;
    height: 100%;
    background: var(--status-idle);
    transform-origin: left;
    transition: transform var(--motion-base) var(--ease-standard), background var(--motion-base) var(--ease-standard);
  }
  /* Not enough yet: a warning while typing; an error once the core refused it. */
  .fill[data-tone="weak"] { background: var(--status-warning); }
  .fill[data-tone="refused"] { background: var(--status-error); }
  .fill[data-tone="fair"], .fill[data-tone="good"] { background: var(--status-connected); }
  .word { color: var(--text-muted); font-size: var(--text-sm); }
  .word[data-tone="weak"] { color: var(--status-warning); }
  .word[data-tone="refused"] { color: var(--status-error); }
  .word[data-tone="fair"], .word[data-tone="good"] { color: var(--status-connected); }
  .mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
</style>
